      piped_rBits_tcCtrl_dataTypeB <= io_in_bits_tcCtrl_dataTypeB;
      piped_rBits_tcCtrl_mixPrecision <= io_in_bits_tcCtrl_mixPrecision;
      piped_rBits_tcCtrl_Sparisity <= io_in_bits_tcCtrl_Sparisity;
      piped_rBits_tcCtrl_DAddress <= io_in_bits_tcCtrl_DAddress;
      piped_rBits_tcCtrl_clear <= io_in_bits_tcCtrl_clear;
      piped_rBits_tcCtrl_M <= io_in_bits_tcCtrl_M;
      piped_rBits_tcCtrl_N <= io_in_bits_tcCtrl_N;
      piped_rBits_tcCtrl_K <= io_in_bits_tcCtrl_K;
      piped_rBits_tcCtrl_OutputD_Idx_m_mix <= io_in_bits_tcCtrl_OutputD_Idx_m_mix;
      piped_rBits_tcCtrl_OutputD_Idx_n_mix <= io_in_bits_tcCtrl_OutputD_Idx_n_mix;
      piped_rBits_tcCtrl_OutputD_Idx_m_f32 <= io_in_bits_tcCtrl_OutputD_Idx_m_f32;
      piped_rBits_tcCtrl_OutputD_Idx_n_f32 <= io_in_bits_tcCtrl_OutputD_Idx_n_f32;
      piped_rBits_throughout_maxE <= io_in_bits_throughout_maxE;
      piped_rBits_throughout_c <= io_in_bits_throughout_c;
      piped_rBits_throughout_rm <= io_in_bits_throughout_rm;
