      automatic logic [26:0] mag =
        io_in_bits_sigSigned[26] ? ~io_in_bits_sigSigned + 27'h1 : io_in_bits_sigSigned;
      automatic logic [4:0]  lzCount =
        mag[25]
          ? 5'h0
          : mag[24]
              ? 5'h1
              : mag[23]
                  ? 5'h2
                  : mag[22]
                      ? 5'h3
                      : mag[21]
                          ? 5'h4
                          : mag[20]
