                                                      : mag[13]
                                                          ? 5'hC
                                                          : mag[12]
                                                              ? 5'hD
                                                              : mag[11]
                                                                  ? 5'hE
                                                                  : mag[10]
                                                                      ? 5'hF
                                                                      : mag[9]
                                                                          ? 5'h10
                                                                          : mag[8]
                                                                              ? 5'h11
                                                                              : mag[7]
                                                                                  ? 5'h12
                                                                                  : mag[6]
                                                                                      ? 5'h13
